    reason: 'outside-press';
    event: MouseEvent | PointerEvent | TouchEvent;
} | {
    reason: 'list-navigation';
    event: KeyboardEvent;
} | {
    reason: 'focus-out';
    event: KeyboardEvent | FocusEvent;
